/*
 * XDP program that drops UDP packets destined for port 53
 * when the DNS query name exceeds 512 bytes.
 *
 * The program follows these steps:
 *   1. Attach to XDP hook (e.g., eth0).
 *   2. Reserve space at the head of the packet for header parsing.
 *   3. Load Ethernet, IPv4 and UDP headers using bpf_skb_load_bytes.
 *   4. Verify we have enough bytes for Ethernet + IPv4 + UDP headers.
 *   5. Check Ethernet type == ETH_P_IP.
 *   6. Verify IP version == IPv4.
 *   7. Verify protocol == IPPROTO_UDP.
 *   8. Load the first byte after the UDP header – this is the DNS
 *      query name length (RFC 1035).
 *   9. If name length > 512, return XDP_DROP; otherwise continue.
 */

#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>

/* Maximum allowed UDP payload size */
#define MAX_UDP_PAYLOAD    (512U)

/* Helper macro for logging – prints to /sys/kernel/debug/tracing */
#define LOG(fmt, ...) bpf_trace_printk(fmt, sizeof(fmt), ##__VA_ARGS__)

SEC("xdp")
int xdp_drop_oversized_dns(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;
    struct iphdr *ip = data + sizeof(*eth);
    struct udphdr *udp = data + sizeof(*eth) + sizeof(*ip);
    __u32 udplen;
    __u8 dnsnamelen;

    /* Ensure we have enough bytes for Ethernet + IPv4 + UDP headers */
    if ((void *)eth + sizeof(*eth) > data_end ||
        (void *)ip + sizeof(*ip) > data_end ||
        (void *)udp + sizeof(*udp) > data + MAX(sizeof(*eth), sizeof(*ip)))
        return XDP_PASS; // Not enough data – let packet continue

    /* Verify Ethernet type is IPv4 */
    if (eth->h_proto != bpf_htons(ETHTYPE))
        return XDP_PASS;

    /* Verify IP version is IPv4 */
    if (ip->version != IPVERSION)
        return XDP_PASS;

    /* Verify protocol is UDP */
    if (ip->protocol != IPPROTO)
        return XDP_PASS;

    /* Load DNS query name length – first byte after UDP header */
    dnsnamelen = udp->len - sizeof(*udp);

    /* Sanity check: ensure we have at least one byte for name length */
    if ((void *)udp + sizeof(*udp) > data)
        return XDP_PASS;

    /* Drop only when payload exceeds 512 bytes */
    if (dnsnamelen > MAXUDPPAYLOAD)
        return bpf_redirect(XDPDROP); // Drop silently via redirect to drop path

    LOG("Dropping oversized DNS query: %u bytes", dnsnamelen);
    return XDPDROP; // Continue processing after logging
}
