int parse_ip_options(struct __sk_buff *skb)
{
    void *data = (void *)(long)skb->data;
    void *end  = (void *)(long)skb->data + skb->len;   // total packet size known at load time via BTF/BTF info in newer kernels.

static inline bool inrange(__u64 ptr, __u64 len) {
        return ptr >= (__u64)data && ptr + len <= (__u64)end;
}

