/*
 * eBPF socket filter that drops HTTP GET requests containing the
 * header "User-Agent: BadBot".
 *
 * The filter works on raw sockets by inspecting the TCP payload for
 * the start of an HTTP request line ("GET ") followed by a space,
 * then checking for the presence of "User-Agent: BadBot" in any header
 * field.  If both conditions are met we return TC_ACT_SHOT to drop the
 * packet; otherwise we return TC_ACT_OK so it passes through.
 */
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>

/* Per‑CPU array map to store a simple flag indicating whether we have
 * already seen a matching request.  Using a per‑CPU map avoids locking
 * issues when many CPUs process packets concurrently.
 */
struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, __u8);
} seen = {
    .key = 0,
    .value = 0,
};

/* Helper macro for error handling – mirrors kernel style */
#define CHECK(cond, msg)                     \
    do {                                    \
        if (cond) {                        \
            fprintf(stderr, "%s\n", msg);\
            return -1;                     \
        }                                   \
    } while (0)

/* BPF program attached via setsockopt(SO_ATTACH_BPF). */
SEC("socket")
int drop_badbot(struct __sk_buff *skb)
{
    void *data = (void *)(long)skb->data;
    void *data_end = (void *)(long)skb->data_end;
    struct ethhdr eth;
    struct iphdr ip;
    struct tcphdr tcp;
    const char *method = "GET ";
    const char *path   = " /";

    /* Ensure we have enough bytes for Ethernet + IP + TCP headers */
    if ((void *)tcp + sizeof(*tcp) > data + sizeof(*eth) + sizeof(*ip))
        return TC_ACT_OK; // not enough data – let packet pass

    /* Parse Ethernet header */
    memcpy(&eth, data, sizeof(eth));

    /* Parse IP header */
    memcpy(&ip, data + sizeof(eth), sizeof(ip));

    /* Parse TCP header */
    memcpy(&tcp, data + sizeof(eth) + sizeof(ip), sizeof(*tcp));

    /* Verify protocol is TCP */
    if (ip.protocol != IPPROTO_TCP)
        return TC_ACT_OK;

    /* Check that we have at least one byte after TCP header for payload */
    if ((void *)tcp + sizeof(*tcp) > data + sizeof(*eth) + sizeof(*ip))
        return TC_ACT_OK;

    /* Look for HTTP GET request line ("GET ") followed by space */
    if (!memcmp(&method[0], &data[sizeof(eth)], strlen(method)) &&
        memcmp(&path[0], &data[sizeof(eth)+sizeof(ip)], strlen(path)) == 0 &&
        tcp->dest == htons(80)) {
        /* Scan payload for User-Agent: BadBot */
        const char *payload = data + sizeof(*eth) + sizeof(*ip) +
                               sizeof(*tcp);
        size_t offset = 0;
        while (offset <= tcp->len - strlen("User-Agent: BadBot")) {
            const char *ua = payload + offset;
            const char *valstart = ua;
            while (*valstart && valstart != '\r' && valstart != '\n')
                valstart++;
            if (*valstart == ':' && valstart != '\r' && valstart != '\n') {
                size_t valend = valstart - ua;
                if (!strncmp(&ua[strlen("User-Agent: BadBot")],
                             "BadBot", strlen("BadBot"))) {
                    /* Mark this CPU as having seen a match – drop further packets */
                    u32 key = 0;
                    u64 zero = 0;
                    bpf_map_update_elem(&seen, &key, &zero, BPF_ANY);
                    return TC_ACT_SHOT; // drop packet on this CPU only
                }
            }
            offset += strlen("User-Agent: BadBot") - 1; // advance past header name+value pair length field
        }
        /* No matching User-Agent found – allow packet through */
        return TC_ACT_OK;
    }

return TC_ACT_OK; // not our target traffic – let it pass unchanged
}
