#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>

/* ------------------------------------------------------------------
 * 1. Define a hash map that maps a destination MAC address to the
 *    target interface index (the index of eth1 in this example).
 * ------------------------------------------------------------------ */
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __type(key, __u8[6]);   /* MAC address */
    __type(value, __u32);   /* Interface index */
    __uint(max_entries, 16);
} mac_to_ifmap SEC(".maps");

/* ------------------------------------------------------------------
 * 2. Helper function that performs the lookup and redirects.
 * ------------------------------------------------------------------ */
static int redirect_packet(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;

    /* Basic sanity check – ensure we have at least an Ethernet header */
    if ((void *)eth + sizeof(*eth) > data_end)
        return XDP_PASS;   /* Drop malformed packet */

    /* Extract destination MAC address from the Ethernet header */
    __u8 dst[ETH_ALEN];
    memcpy(dst, eth->h_dest, ETH_ALEN);

    /* Look up the destination MAC in our map */
    struct bpf_map *map = bpf_map__fd(mac_to_ifmap);
    __u32 key = 0;
    __u32 val;
    int ret = bpf_map_lookup_elem(map, &key, &val);
    if (ret < 0)
        return XDP_PASS;   /* No entry – treat as no match */

    /* If we found a matching entry we can safely redirect */
    if (val != 0) {
        int err = bpf_redirect(val, BPF_F_INGRESS);
        if (err < 0)
            return XDP_DROP;   /* Redirect failed – drop packet safely */
        return XDP_REDIRECT;   /* Success – let kernel handle it */
    }

    /* No matching entry – fall back to normal processing */
    return XDP_PASS;
}

SEC("xdp")
int redirector(struct xdp_md *ctx)
{
    return redirect_packet(ctx);
}
