#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>

/* Maximum UDP payload we are willing to inspect */
#define MAX_UDP_PAYLOAD 64

/* Drop NTP amplification packets */
SEC("xdp")
int xdp_drop_ntp(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;
    struct iphdr  *ip;
    struct udphdr *udp;
    __u8       src[2];
    __u16      sport;
    __u16      len;
    __u32      pktlen;

    /* Ethernet header – must be present */
    if ((void*)(eth + 1) > data_end)
        return XDP_PASS; // not enough data for Ethernet header

    /* IPv4 header – must be present after Ethernet */
    if ((void*)(eth + 1) > data_end)
        return XDP_PASS;

    ip = data + sizeof(*eth);
    if ((void*)(ip + 1) > data_end)
        return XDP_PASS;

    /* UDP header – must be present after IPv4 */
    if ((void*)(ip + 1) > data_end)
        return XDP_PASS;

    udp = data + sizeof(*eth) + sizeof(*ip);
    if ((void*)(udp + 1) > data_end)
        return XDP_PASS;

    /* Extract source port (network byte order) */
    sport = bpf_ntohs(udp->source);

    /* Check for NTP source port (123) */
    if (sport == bpf_htons(123)) {
        /* Payload length field is stored in udp->len (network order) */
        len = bpf_ntohs(udp->len);
        pktlen = sizeof(*eth) + sizeof(*ip) + sizeof(*udp);
        /* Ensure we have at least the UDP header before reading len */
        if ((void*)(udp + 1) > data_end)
            return XDP_PASS; // malformed packet – cannot trust len field
        if (len <= 400 || len > MAX_UDP_PAYLOAD)
            return XDP_DROP; // drop too short or too long payloads
        /* At this point we know len is within [400, MAX] and safe to read */
        LOG("Dropping NTP amplification packet: src=%u dst=%u len=%u", sport, ip->daddr, len);
        return XDP_DROP; // drop malicious packet silently
    }

    /* Normal traffic – let it pass through */
    return XDP_PASS;
}

char _license[] SEC("license") = "GPL";
```
**Explanation of the code**
- **Header parsing**: The program walks the packet buffer step‑by‑step (`data` pointer advances by each protocol header size). It first checks that enough bytes exist for each layer before dereferencing.
- **Source‑port filter**: `sport == bpf_htons(123)` matches the NTP service port.
- **Payload‑length check**: `len` is converted from network byte order with `bpf_ntohs`. The code ensures `len` is within a safe range (`400 <= len <= MAX`) before accessing the payload.
- **Logging**: `LOG` prints a concise message with source IP, destination IP, and payload length when a drop occurs.
- **Drop decision**: Returning `XDP_DROP` silently discards the packet; returning `XDP_PASS` lets legitimate traffic continue.
- **Safety considerations**:
  - All pointer arithmetic stays within `data`/`data+pktlen`, preventing out‑of‑bounds reads.
  - The program does not modify packet contents; it only drops based on metadata.
  - Using `bpf_*` helpers ensures verifier compliance.

**Why this mitigates amplification**
NTP amplification attacks rely on reflectors sending large responses to spoofed victims. By dropping any UDP packet whose source port is NTP **and** whose payload exceeds a reasonable size (>400 bytes), we remove the most common reflector traffic while allowing normal NTP queries (<400 bytes). This reduces both bandwidth consumption on the victim side and processing load on the reflector.

