/*
 * XDP Generic Software Load Balancer (GSLB)
 *
 * This program hashes the 5‑tuple (src/dst IP, src/dst port, protocol)
 * and forwards matching packets to one of two backend IPs stored in a
 * BPF array map. The hash is computed with a simple XOR‑based function
 * that fits within the verifier's instruction limits.
 */

#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <bpf/bpf_helpers.h>

/* ------------------------------------------------------------------
 * 1. BPF map definition – holds the two backend IPv4 addresses.
 * ------------------------------------------------------------------ */
struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 2);
    __type(key, __u32);   // key = 0 for backend[0], 1 for backend[1]
    __type(value, __u32); // value = IPv4 address in network byte order
} backend_map SEC(".maps");

/* ------------------------------------------------------------------
 * 2. Helper macros – keep the code readable and verifier‑friendly.
 * ------------------------------------------------------------------ */
#define HASH_IP(src, dst) ((src) ^ (dst))
#define HASH_PORT(sport, dport) ((sport) ^ (dport))
#define HASH_PROTO(proto) ((proto) << 8)

/* ------------------------------------------------------------------
 * 3. XDP entry point – called for every packet that reaches the NIC.
 * ------------------------------------------------------------------ */
SEC("xdp")
int xdp_glb(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;
    struct iphdr   ip;
    struct tcphdr  tcp;

    /* ----- Ethernet header ----- */
    if ((void*)(eth + 1) > data_end)
        return XDP_PASS; // malformed frame
    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS; // not IPv4 – drop or forward elsewhere

    /* ----- IPv4 header ----- */
    ip = *(struct iphdr *)((void *)eth + sizeof(*eth));
    if ((void*)(ip + 1) > data_end)
        return XDP_PASS;

    /* ----- TCP header (optional – only needed for port hashing) ----- */
    if (ip->protocol == IPPROTO_TCP && ctx->len >= sizeof(*tcp)) {
        tcp = *(struct tcphdr *)((void *)ip + sizeof(*ip));
        if ((void*)(tcp + 1) > data_end)
            return XDP_PASS;
        sport = bpf_ntohs(tcp->source);
        dport = bpf_ntohs(tcp->dest);
        h = HASH_IP(ip->saddr, ip->daddr);
        h += HASH_PORT(sport, dport);
        h += HASH_PROTO(ip->protocol);
        idx = h % 2; // selects backend[0] or backend[1]
        newip.saddr = backend[idx].saddr; // rewrite source IP as well for symmetry
        newip.daddr = ip->daddr;      // destination stays unchanged until later rewrite
        newip.ihl = ip->ihl;
        newip.version = ip->version;
        newip.tos   = ip->tos;
        newip.tot_len = htons((sizeof(*newip)));
        newip.id     = htons((__u16)(bpf::getpid() & 0xFFFF));
        newip.frag   |= htons((__u16)(h >> 16));
    }

    /* ----- Destination IP rewrite ----- */
    struct iphdr newiph;
    memcpy(&newiph, &newip, sizeof(newiph));
    newiph.daddr = backend[idx].saddr; // now destination points to a backend server

    /* ----- Forwarding decision ----- */
    if (!newiph.daddr || !newiph.ihl || !newiph.version || !newiph.tot_len ||
        !newiph.__unused[0] || !newiph.__unused[1])
        return XDP_PASS; // malformed packet after rewrite – drop safely

    /* In a real implementation we would use bpf helper to update the packet buffer.
     * For illustration we simply return XDP_TX so the kernel will transmit the packet.
     */
    return XDP_TX; // forward to NIC driver for actual transmission
}
```
