/*
 * XDP program that drops overlapping IP fragments.
 *
 * It runs at the `xdp` hook on every incoming packet.
 * For each fragment we:
 *   1. Verify we have enough headroom for the fragment header.
 *   2. Parse the fragment header (offset and MF flag).
 *   3. If offset != 0 && MF == 1 → overlapping fragment → drop.
 *   4. Otherwise continue processing (e.g., forward to next stage).
 */

#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/udp.h>

/* Helper macro for error handling */
#define CHECK(cond, msg)                     \
    do {                                    \
        if (cond) {                         \
            bpf_trace_printk(msg "\n");    \
            return XDP_DROP;               \
        }                                   \
    } while (0)

SEC("xdp")
int xdp_frag_drop(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct iphdr ip4;
    struct ipv6hdr ip6;
    __u8 proto;

    /* Ensure we have at least an IPv4 header */
    if ((void *)data + sizeof(struct iphdr) > data_end)
        return XDP_DROP;

    /* Load IPv4 header */
    ip4 = *(struct iphdr *)data;
    proto = ip4.protocol;

#if defined(__KERNEL__)
    /* If protocol is IPv6 we need to check for IPv6 fragments as well */
#endif

#if defined(__KERNEL__)
    if (proto == IPPROTO_FRAGMENT) {
        /* Verify we have enough bytes for fragment header */
        if ((void *)data + sizeof(struct iphdr) > data_end)
            return XDP_DROP;

        /* Copy fragment header into stack variable safely */
        struct iphdr fraghdr = *(struct iphdr *)data;
        __u8 flags = fraghdr.fragments & 0x1F; // lower 5 bits: offset+MF+reserved
        __u8 fraglen = ntohs(fraghdr.fraglen);

        /* Overlap detection: non‑zero offset AND MF set -> overlap */
        if ((flags & 0x1F) && (flags & 0x20)) {
            bpf_trace_printk("Dropping overlapping fragment\n");
            return XDP_DROP; // drop this packet immediately
        }

        /* If this is the first fragment of a new packet, accept it */
        if (!(flags & 0x20)) { // MF cleared -> start of new packet
            return XDP_PASS; // let other programs handle it further downstream
        }
    }
#endif

    /* Normal path – let other programs handle the packet */
    return XDP_PASS;
}
```
**Explanation of key steps**
1. **Hook selection** – `SEC("xdp")` places the program at the earliest point in the receive path (`xdp`), allowing us to inspect every incoming packet before it reaches higher layers.
2. **Header validation** – We first ensure there is enough space for an IPv4 header (`sizeof(struct iphdr)`). For IPv6 we would repeat similar checks after confirming `proto == IPPROTO_FRAGMENT`.
3. **Fragment parsing** – The code copies the fragment header into a stack variable (`fraghdr`) to avoid pointer aliasing issues inside eBPF helpers.
4. **Overlap detection** – The mask `0x1F` extracts bits `[7:5]` (offset+MF+reserved). If both offset (`bits[7:5]`) and MF (`bit[7]`) are set, the packet overlaps with a previously seen fragment → drop.
5. **First‑fragment acceptance** – When MF is cleared (`bit[7] == 0`), this is the start of a new datagram; we simply pass it onward.
6. **Safety considerations** – All memory accesses stay within `data`/`data_end`. No helper calls are used beyond what eBPF permits (`bpf_trace_printk`). The program returns `XDP_PASS` or `XDP_DROP`, which are standard actions for further processing or immediate discard.
