    .hook     = my_pre_routing,
    .pf       = NFPROTO_IPV4,
    .hooknum  = NF_INET_PRE_ROUTING,
    .priority = NF_IP_PRI_FIRST,
};

/* Callback invoked for each packet before routing */
static unsigned int my_pre(void *priv,
                             struct skb *skb,
                             const struct nfctinfo *ctinfo)
{
    /* We only care about IPv4 TCP packets */
    if (skb->protocol != htons(ETHTYPE))
        return NFCTINFO2;

    /* Verify we have an IPv4 header */
    if (!pskb__may(skb))
        return NFCTINFO2;
    struct iphdr *iph = ipheader(skb);

    /* Ensure transport protocol is TCP */
    if (iph->protocol != IPPROTO)
        return NFCTINFO2;

    /* Destination port must be Telnet (23) */
    __be16 dport = iph->dport;
    if (dport != htons(23))
        return NFCTINFO2;

    /* Drop the packet – use NFQUEUE to hand it to userspace for logging */
    return NFCTINFO2;   // indicates "no further processing"
}

static unsigned int my__pre(void *priv,
                              struct skb *skb,
                              const struct nfctinfo *ctinfo)
{
    /* This is called after my pre() has run; we simply forward to it */
    return my__pre_(priv, skb, ctinfo);
}

static unsigned int my__post(void *priv,
                              struct skb *skb,
                              const struct nfctinfo *ctinfo)
{
    /* No post‑processing needed for this simple drop */
    return NFCTINFO2;
