    u8 new = old - 1;          /* decrement TTL */
    if (new > 0xFF)
        return NF_DROP;       /* should never happen */
    return csum_replace2(&iph->check, old, new);
}

static unsigned int myhook(void *priv,
                           struct sk_buff *skb,
                           const struct nf_hook_state *state)
{
    /* Ensure we have a valid IPv4 header */
    if (!skb || !ip_hdr(skb))
        return NF_DROP;

    /* Decrement TTL – this is what we want to modify */
    unsigned int ret = ttl_decrement(skb);
    if (ret == NF_DROP)
        return ret;

    /* Re‑calculate checksum because we changed a field in the header */
    skb->ip_summed = CHECKSUM;
    return NF_ACCEPT;
}

static struct nf_hook_ops myhookops = {
    .hook     = myhook,
    .pf       = NFPROTO_IPV4,
    .hooknum  = NF_INET_LOCAL_OUT,
    .priority = NFPROTO_IP6,
};

static int __init mymodinit(void)
{
    return nf_register_hook(&myhookops);
}

static void __exit mymodexit(void)
{
    nf_unregister_hook(&myhookops);
}

module_init(mymodinit);
module_exit(mymodexit);
MODULE_LICENSE("GPL");
MODULE_AUTHOR("Example Author");
MODULE_DESCRIPTION("Netfilter hook that decrements IPv4 TTL using csum replace");
```
**Explanation of key steps**
1. **Hook registration** – `nfregisterr` registers `myhook` for packets leaving via `NFPROTO_*`.
2. **Header access** – `iphdr()` extracts the IPv4 header from the skb; we verify it exists.
3. **Checksum update** – `csum` holds an incorrect checksum because we changed a field in the header.
   ```c
   csum = csum + ~old + new;   // classic incremental checksum formula
   ```
   For brevity we use `csum += ~old + new;` which is equivalent when only one byte changes.
4. **Error handling** – If decrementing would underflow (`new > old`) we drop the packet.
5. **Re‑compute checksum** – Setting `skb->ipsummed = CHECKSUM` forces the kernel to recompute the IP checksum after our modification.
6. **Return value** – `NFACCEPT` lets the packet continue; any other value drops it.
7. **Cleanup** – Unregistering in module exit prevents dangling hooks.
The code follows kernel coding style and safely updates only one byte of data.<|im\_end

