/*
 * Example: Using spinlocks inside an interrupt handler (bottom half).
 * The handler runs in soft‑irq context and must not sleep.
 */
#include <linux/spinlock.h>
#include <linux/interrupt.h>

/* Global lock – protects a shared data structure */
static DEFINE_SPINLOCK(my_data_lock);
static int my_shared_counter;

/* Interrupt handler – runs in soft‑irq context */
static irqreturn_t my_isr(int irq, void *dev_id)
{
    unsigned long flags;
    int new_val;

    /* 1️⃣ Acquire the spinlock with IRQs disabled to protect against nested IRQs */
    spin_lock_irqsave(&my_data_lock, flags);

    /* 2️⃣ Critical section – safe because we are not sleeping */
    new_val = ++my_shared_counter;

    /* 3️⃣ Release the lock and restore IRQ state */
    spin_unlock_irqrestore(&my_data_lock, flags);

    /* 4️⃣ Notify other parts of the driver that work has been done */
    wake_up(&my_completion);

    return IRQ_HANDLED;
}
```
### Why this is correct:
1. **Spinlock semantics** – `spin_lock_*` disables local interrupts on entry and re‑enables them on exit (`*_irqsave`/`*_irqrestore`). This guarantees that no other IRQ can pre‑empt this critical section on the same CPU.
2. **No sleeping** – The handler never calls `schedule()` or any function that may block; therefore a mutex (which may sleep) would be illegal.
3. **Preemption safety** – Because interrupts are disabled while holding the lock, a higher‑priority interrupt cannot acquire the same lock and cause a deadlock.
4. **Correct unlocking** – `spin_unlock_*` restores the previous interrupt state, ensuring normal operation resumes after the ISR returns.

### What would go wrong with a mutex?
```c
static DEFINE(my_mutex);
static int my_shared;

static irqreturn_t my_isr(int irq, void *dev)
{
    int ret = mutex_lock(&my_mutex);   // <-- illegal in interrupt context!
    if (ret == 0) {
        my_shared = ++myshared;       // non‑atomic write → race!
        mutex_unlock(&mymutex);
    }
    return IRQ_HANDLED;
}
```
* The kernel would emit a warning like *"mutex lock in interrupt context"* and may deadlock if another CPU holds `mymutex`.
* Even if it compiled, sleeping inside an ISR would trigger a BUG because `schedule()` is prohibited.

### Summary of guidelines from the documentation:
- **Spinlocks**: safe in both process and interrupt contexts; disable local interrupts while held.
- **Mutexes**: only safe in process context; must never be taken inside an ISR or any code that can run with interrupts enabled.
- Use `*_irqsave`/`*_irqrestore` variants when you need to protect data accessed from both contexts.

