/*
 * udp_log_module.c – Simple Netfilter UDP logging module
 *
 * This module registers a Netfilter hook that runs for every outgoing
 * UDP packet. It extracts the source port, destination port and packet
 * length from `struct sk_buff` and prints them with `pr_info()`.
 */

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/netfilter.h>
#include <linux/netfilter_ipv4.h>
#include <linux/skbuff.h>
#include <linux/udp.h>

/* Hook function – called for each outgoing UDP packet */
static unsigned int udp_log_hook(void *priv,
                                 struct sk_buff *skb,
                                 const struct nf_hook_state *state)
{
    const struct udphdr *uh;
    u16 src_port, dst_port;
    u16 len;

    /* Ensure we have enough data for a UDP header */
    if (skb->len < sizeof(struct udphdr))
        return NF_ACCEPT; /* drop malformed packets */

    uh = (const struct udphdr *)skb->data;
    src_port = ntohs(uh->source);
    dst_port = ntohs(uh->dest);
    len = ntohs(uh->len);

    pr_info("[UDP LOG] src=%u dst=%u len=%u\n", src_port, dst_port, len);
    return NF_ACCEPT; /* continue normal processing */
}

static struct nf_hook_ops udp_log_ops = {
    .hook     = udp_log_hook,
    .pf       = NFPROTO_IPV4,
    .hooknum  = NF_INET_POST_ROUTING,
    .priority = NF_IP_PRI_FIRST,
};

static int __init udplog_init(void)
{
    int ret;

    pr_info("[UDP LOG] loading module\n");
    ret = register_netfilter(&udplog_ops);
    if (ret) {
        pr_err("[UDP LOG] failed to register hook (err=%d)\n", ret);
        return ret;
    }
    return 0;
}

static void __exit udplog_exit(void)
{
    pr_info("[UDP LOG] unloading module\n");
    unregister_netfilter(&udplog_ops);
}

module_init(udplog_init);
module_exit(udplog_exit);
MODULE_LICENSE("GPL");
MODULE_{NAME}_DESCRIPTION("Netfilter UDP logging module");
MODULE_{NAME}_AUTHOR("SFT Example Generator");
```
**Explanation of key parts**
- `nf_*` helpers are used instead of raw pointers because they perform type‑safe checks.
- The hook runs in the **POST‑ROUTING** stage (`NFPROTO\_IPV4`, `NF\_INET\_POST\_ROUTING`), which is appropriate for logging before the packet leaves the host.
- `pr_*` macros emit messages to the kernel log buffer; they are safe in any context where printk is allowed.
- The module registers itself with `register_*` functions and cleans up with `unregister_*` on exit.
- No special privileges are required beyond being able to load a kernel module.<|im\_end|>
