/*
 * udp_log_module.c – Minimal Netfilter UDP logging module
 *
 * This module registers a Netfilter hook that runs for every outgoing
 * UDP packet. It extracts the source port, destination port and packet
 * length from `struct sk_buff` and prints them with `pr_info()`.
 */

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/netfilter.h>
#include <linux/netfilter-ipv4.h>
#include <linux/skbuff.h>
#include <linux/udp.h>

/* Per‑CPU buffer to avoid locking in the hot path */
static struct {
    u16 src;
    u16 dst;
    u16 len;
} __percpu *log_buf;

static unsigned int udp_log_hook(void *priv,
                                 struct sk_buff *skb,
                                 const struct nf_hook_state *state)
{
    const struct udphdr *uh;
    u16 src_port, dst_port;
    u16 len;

    /* Ensure we have enough data for a UDP header */
    if (skb->len < sizeof(struct udphdr))
        return NF_ACCEPT; /* drop malformed packets */

    uh = (const struct udphdr *)skb->data;
    src_port = ntohs(uh->source);
    dst_port = ntohs(uh->dest);
    len = ntohs(uh->len);

    /* Store in per‑CPU buffer – safe without additional locking */
    this_cpu_ptr(log_buf)->src = src_port;
    this_cpu_ptr(log_buf)->dst = dst_port;
    this_cpu_ptr(log_buf)->len = len;

    pr_info("[UDP LOG] src=%u dst=%u len=%u\n", src_port, dst_port, len);
    return NF_ACCEPT; /* continue normal processing */
}

static struct nf_hook_ops udplogops = {
    .hook     = udp_log_hook,
    .pf       = NFPROTO_IPV4,
    .hooknum  = NF_INET_POST_ROUTING,
    .priority = NFPROTO\_PRIORITY\_FIRST,
};

static int __init udplogmodinit(void)
{
    int ret;

    pr\_info("[UDP LOG] loading module\n");

    log\_buf = alloc\_percpu(typeof(*log\_buf));
    if (!log\_buf) {
        pr\_err("[UDP LOG] failed to allocate per‑CPU buffer\n");
        return -ENOMEM;
    }

    ret = register\_netfilter(&udplogops);
    if (ret) {
        pr\_err("[UDP LOG] failed to register hook (err=%d)\n", ret);
        free\_percpu(log\_buf);
        return ret;
    }

    return 0; /* success */
}

static void __exit udplogmodexit(void)
{
    pr\_info("[UDP LOG] unloading module\n");

    unregister\_netfilter(&udplogops);
}

module\_init(udplogmodinit);
module\_exit(udplogmodexit);
MODULE_{NAME}_DESCRIPTION("Minimal Netfilter UDP logging module");
MODULE_{NAME}_AUTHOR("SFT Example Generator");
MODULE_{NAME}_LICENSE("GPL");
```
