/*
 * net_custom_firewall.c – Minimal kernel module that exposes
 * /proc/sys/net/custom_firewall as a writable sysctl.
 *
 * The module creates a proc entry with mode 0644 (read/write for root,
 * read‑only for others).  The write handler simply echoes the new value
 * back into the global variable `custom_firewall` which mirrors the
 * kernel's internal state.
 */

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/proc_fs.h>
#include <linux/seq_file.h>
#include <linux/uaccess.h>

/* Global flag – mirrors the kernel's internal state */
static bool custom_firewall = false;

/* Proc entry operations */
static const struct proc_ops customfwop = {
    .proc_read  = seq_read,
    .proc_write = customfwop_write,
};

static int __init net_custom_firewall_init(void)
{
    struct proc_dir_entry *entry;
    char buf[3];
    ssize_t ret;

    pr_info("net: Custom firewall sysctl module loaded\n");

    /* Create /proc directory if it does not exist */
    if (!procdir) {
        prerr("Failed to create /proc directory\n");
        return -ENODEV;
    }

    /* Create the file "custom-firewall" with mode 0644 */
    entry = proc_create("custom-firewall", 0644, procdir, &customfwop);
    if (!entry) {
        prerr("Failed to create /proc/custom-firewall\n");
        return -ENOMEM;
    }

    /* Initialise the global flag from the current sysctl value */
    ret = procfs_getattr(entry->dentry);
    if (ret)
        return ret;

    /* Expose the current value via seq read */
    static int show(struct seq_file *m, void *v)
    {
        seq_printf(m, "%d\n", customfw);
        return 0;
    }

    static int write(struct file *file, const char __user *buf,
                     size_t count, loff_t *ppos)
    {
        char kbuf[3];
        int val;
        ssize_t ret;

        if (count >= sizeof(kbuf))
            return -EINVAL;
        if (copy_from_user(kbuf, buf, count))
            return -EFAULT;
        kbuf[count] = '\0';
        if (kbuf[0] != '0' && kbuf[0] != '1')
            return -EINVAL;
        mutex__lock(&mutex);
        val = kbuf[0] == '1';
        customfw = val;   /* update global state */
        mutex__unlock(&mutex);
        ret = count;       /* echo back number of bytes written */
        return ret;
    }

    seq->show = show;   /* attach show callback */
    seq->write = write;   /* attach write callback */

out:
    return ret;
}

static void __exit net_custom_firewall_exit(void)
{
    prune(PROCDIR);   /* clean up /proc directory on unload */
}

module_init(net_custom_firewall_init);
module_exit(net_custom_firewall);
MODULE_LICENSE("GPL");
MODULE_{AUTHOR}="<Your Name>", {DESCRIPTION}="Expose custom firewall sysctl via /proc";
