 *
 * Purpose: Register a kprobe on the generic VFS open entry point
 *          (or on do_sys_openat2 if available) to log every
 *          attempt to open /etc/shadow from user space.
 */

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/kprobes.h>
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/slab.h>

/* Buffer to hold the filename string safely */
static char shadow_path[PATH_MAX];
static int shadow_path_len;

/* Probe handler – called for each matching event */
static void shadow_open(struct pt_regs *ctx)
{
    const char __user *filename = (const char __user *)PT_REGS_PARM1(ctx);
    if (!filename)
        return; /* Defensive: should never happen */

    /* Copy the string from user space safely */
    if (copy_from_user(shadow_path, filename, shadow_path_len))
        return; /* In case copy fails – ignore this event */

    /* Log the event – in a real system you would use pr_* or netlink */
    pr_info("[kprobe] do sys open called for %s\n", shadow_path);
}

static struct kprobe kp = {
    .symbol_name = "vfs_open",   /* fallback if do_sys_* not exported */
    .pre_handler = shadow_open,
};

static int __init shadow_monitor_init(void)
{
    int ret;

    pr_info("[shadow] loading module\n");

    /* Allocate memory for the pathname buffer – safe because we only read it */
    shadow = kmalloc(PATH_MAX, GFP_KERNEL);
    if (!shadow) {
        pr_err("[shadow] failed to allocate memory for pathname buffer\n");
        return -ENOMEM;
    }
    memset(shadow, 0, PATH_MAX);

    /* Register the probe */
    ret = register_kprobe(&kp);
    if (ret) {
        pr_err("[shadow] failed to register kprobe: %d\n", ret);
        goto out;
    }

out:
    return ret;
}

static void __exit shadow_monitor__exit(void)
{
    pr_info("[shadow] unloading module\n");

