/*
 * Netfilter hook example – safely read TCP payload using skb_header_pointer()
 * ----------------------------------------------------------
 * The hook receives a struct sk_buff *skb via the NF_INET_PRE_ROUTING
 * (or any other appropriate hook) context. It extracts the TCP header
 * from both linear and non‑linear parts of the packet, then reads the
 * payload safely.
 */
#include <linux/module.h>
#include <linux/skbuff.h>
#include <linux/tcp.h>
#include <linux/netfilter.h>

static unsigned int safe_tcp_payload(struct sk_buff *skb)
{
    const u8 *hdr;
    const u8 *payload;
    size_t hdrlen = sizeof(struct tcphdr);
    size_t plen   = 0;

    /* 1️⃣ Linear part – guaranteed to be contiguous */
    hdr = (const u8 *)skb->data;
    if (!skb_header_pointer(skb, 0, hdrlen,
                           (void **)&hdr)) {
        pr_err("safe: cannot read TCP header from linear part\n");
        return -1; /* indicate failure */
    }

    /* 2️⃣ Non‑linear part – may contain fragmented data */
    if (!skb->head) {
        pr_err("safe: skb has no head (non‑linear)\n");
        return -1;
    }
    payload = (const u8 *)skb->data + hdrlen;
    plen   = skb->len - hdrlen; /* length after TCP header */

    /* 3️⃣ Safely read payload */
    if (!skb_header_pointer(skb, plen,
                           sizeof(u32),   /* read only first 4 bytes as example */
                           (void **)&payload)) {
        pr_err("safe: cannot read payload from non‑linear part\n");
        return -1;
    }

    pr_info("safe: TCP payload length=%zu\n", plen);
    return (int)plen; /* caller can use this length */
}
```
