#include <linux/skbuff.h>
#include <linux/netfilter.h>
#include <linux/netfilter_ipv4.h>

static unsigned int tcp_payload_inspect(struct sk_buff *skb,
                                         struct net *net,
                                         u8 family)
{
    const u8 *hdr;
    const u8 *payload;
    size_t hdrlen = sizeof(struct tcphdr);
    size_t plen   = 0;
    int ret;

