    plen   = skb->len - hdrlen; /* length after TCP header */

    /* Safely read payload */
    ret = skb_header_pointer(skb, plen,
                             sizeof(u32),   /* example: read first 4 bytes as payload */
                             (void **)&payload);
    if (!ret) {
        pr_err("tcp: cannot read payload from non‑linear part\n");
        return NF_DROP;
    }

    pr_info("tcp: payload length=%zu\n", plen);

