#endif

#if defined(CONFIG__KERNEL__) && defined(__x86)
/* Example: check for known shellcode patterns in the first few bytes of the payload */
static const unsigned char shellcode[] = {0x90, 0x90, 0x90};
unsigned char buf[sizeof(shellcode)];
int len = min((int)plen, sizeof(buf));
memcpy(buf, payload, len);
if (memcmp(buf, shellcode, len) == 0) {
    pr_*("shellcode detected!\n"); // replace with appropriate logging macro
}
#endif

return NF_ACCEPT; /* packet continues normal processing after safe inspection */
}
