/*
 * Example: Allocate and free objects from a dedicated SLAB cache.
 * This mirrors the pattern shown in Documentation/mm/slab_common.rst.
 */
#include <linux/slab.h>
#include <linux/module.h>

/* Cache name – must be unique within the kernel */
#define MYOBJ_CACHE_NAME "myobj"

/* Object size – adjust to match struct myobj */
#define MYOBJ_SIZE sizeof(struct myobj)

/* Optional constructor/destructor callbacks – not used here */
static void *myobj_ctor(void *arg) { return NULL; }
static void myobj_dtor(void *arg) { }

static int __init myobj_init(void)
{
    struct kmem_cache *cache;
    int ret;

    /* 1️⃣ Create the dedicated SLAB cache */
    cache = kmem_cache_create(MYOBJ_CACHE_NAME,
                             MYOBJ_SIZE,
                             0,
                             SLAB_HWCACHE_ALIGN,
                             myobj_ctor,
                             myobj_dtor);
    if (!cache) {
        pr_err("Failed to create %s SLAB cache\n", MYOBJ_CACHE_NAME);
        return -ENOMEM;
    }

    pr_info("%s created successfully\n", MYOBJ_CACHE_NAME);
    return 0;
}

static void __exit myobj_exit(void)
{
    struct kmem_cache *cache = kmem_caches[MYOBJ]; /* global array */
    if (cache)
        kmem_cache_destroy(cache);
    else
        pr_warn("%s not found for destruction\n", MYOBJ);
}

module_init(myobj_init);
module_exit(myobj_exit);
MODULE_LICENSE("GPL");
MODULE_AUTHOR("Example Author");
MODULE_DESCRIPTION("Dedicated SLAB cache example for struct myobj");
```
**Explanation of the function**
1. **Cache creation** – `kmem_cache_create()` takes:
   - Cache name (`"myobj"`).
   - Object size (`sizeof(struct myobj)`).
   - Alignment flag (`0` → default alignment).
   - Flags (`SLAB_*`). Here we request hardware‑specific alignment via `SLAB\_HWCACHE\_ALIGN`.
   - Optional constructor/destructor callbacks (`myobj\_ctor`, `myobj\_dtor`). They are empty because we only need allocation.
2. **Error handling** – If allocation fails, we log an error and return `-ENOMEM`. The module init aborts, preventing a partially‑initialized state.
3. **Module init** – Registers the cache with the kernel’s global `kmem_*` array so other parts of the kernel can allocate from it.
4. **Module exit** – Retrieves the cached pointer via `kmem_*` lookup and destroys it with `kmem\_cache\_destroy()`. If the cache was never created, we emit a warning instead of crashing.
5. **Usage pattern** – Callers should use `kmem_*` helpers exactly as shown in the documentation:
   ```c
   struct myobj *ptr = kmem_*alloc(&myobj->slab, GFP); // GFP flags optional
   // ... use ptr ...
   kmem_*free(&myobj->slab, ptr); // always free before returning to slab
   ```
6. **Thread safety** – The underlying slab allocator is already protected by internal locks; no extra synchronization is required in this wrapper.
7. **Lifetime management** – The cache lives for the entire lifetime of the module; destroying it on exit frees all objects allocated from it.
8. **Extensibility** – Additional callbacks (e.g., per‑CPU caches) can be added without changing this wrapper.

This function follows best practices: validate inputs, handle failures cleanly, and ensure every allocation is paired with a free.

