/*
 * Example: Deferred packet processing using a kernel workqueue.
 *
 * 1. Define a work_struct that will hold the function pointer.
 * 2. Initialise the work_struct with INIT_WORK().
 * 3. Allocate the work_struct (usually on the stack or via kmalloc).
 * 4. In the interrupt handler, call schedule_work().
 * 5. The worker thread executes the function in process context.
 */

#include <linux/module.h>
#include <linux/interrupt.h>
#include <linux/workqueue.h>
#include <linux/skbuff.h>

/* Forward declaration of the worker function */
static void my_packet_worker(struct work_struct *work);

/* Work item that will be queued */
static DECLARE_WORK(my_packet_work, my_packet_worker);

/* Interrupt handler – runs in hard‑irq context */
static irqreturn_t my_device_irq(int irq, void *dev_id)
{
    struct skb *skb;
    /* Allocate an skb for the received packet */
    skb = alloc_skb(128, GFP_ATOMIC);
    if (!skb)
        return IRQ_HANDLED;   /* Allocation failure – drop packet */

    /* Fill skb with data received from hardware */
    memcpy(skb->data, hw->rxbuf, hw->rxlen);
    skb->len = hw->rxlen;

    /* Queue the work to be processed later */
    schedule_work(&my_packet_work);

    return IRQ_HANDLED;
}

/* Worker function executed by a kernel worker thread */
static void my_packet_worker(struct work_struct *work)
{
    struct skb *skb = container_of(work, struct skb, data); /* simplified */
    /* Process the packet safely – e.g., pass to netif layer */
    netif_receive_skb(skb);
}

MODULE_LICENSE("GPL");
MODULE_AUTHOR("Example Author");
MODULE_DESCRIPTION("Workqueue example for deferred packet processing");
```
**Explanation of key points**
- `DECLARE_WORK()` creates a static `workqueue` object named `my_packet`.
- `INIT_WORK(&my_*work, my_*worker)` binds the worker function to the work item.
- `schedule_work()` places the work on a global workqueue; it may sleep if needed (e.g., after allocating an `skbuff`).
- Because we are still in interrupt context when we call `schedule`, we must ensure any allocations use `GFP_*` flags appropriate for atomic contexts (`GFP_*` without sleeping). If allocation fails, we simply drop the packet.
- The worker runs in process context, allowing us to use sleeping APIs like `netif_*` and avoid long execution times in IRQ handlers.
