#define DEVICE_PHYS_BASE   0xF0000000UL
/* Size of the register block we need – assume 4 KB */
#define DEVICE_REG_SIZE    0x1000UL

static void __iomem *device_regs;
static int __init mydev_init(void)
{
    /* Map the device registers */
    device_regs = ioremap(DEVICE_PHYS_BASE, DEVICE_REG_SIZE);
    if (!device_regs) {
        pr_err("mydev: ioremap failed\n");
        return -ENOMEM;
    }
    pr_info("mydev: MMIO region mapped at %p\n", device_regs);
    return 0;
}

static void __exit mydev_exit(void)
{
    if (device_regs)
        iounmap(device_regs);
    pr_info("mydev: MMIO region unmapped\n");
}

module_init(mydev_init);
module_exit(mydev_exit);
MODULE_LICENSE("GPL");
MODULE_AUTHOR("Example Author");
MODULE_DESCRIPTION("Simple MMIO driver using ioremap/iounmap");
