/*
 * Minimal lock‑less ring buffer used for communication between two CPUs.
 * The producer writes data into `buf` at position `head` and then
 * publishes the new tail index after ensuring all stores are visible.
 * The consumer reads from position `tail` and then ensures it sees all
 * stores performed by the producer.
 */
#define RING_SIZE   64
#define DATA_SIZE   16

struct ring {
    char buf[RING_SIZE][DATA_SIZE];
    int head;   /* Producer index */
    int tail;   /* Consumer index */
};

/* Producer side – write data, then publish new tail */
static void producer(struct ring *r)
{
    int i;
    /* Fill some slots */
    for (i = 0; i < DATA_SIZE; ++i)
        r->buf[r->head][i] = 'A' + i;

    /* Ensure all stores to buf are globally visible before updating tail */
    smp_wmb();               /* Write memory barrier – prevents reordering of stores */
    r->tail = r->head;      /* Publish new tail index */
}

/* Consumer side – read data, then ensure we see all stores from producer */
static void consumer(struct ring *r)
{
    int i;
    while (r->tail != r->head) {   /* Wait until there is something to read */
        smp_rmb();               /* Read memory barrier – prevents reordering of loads */
        for (i = 0; i < DATA_SIZE; ++i)
            printf("%c ", r->buf[r->tail][i]);
        printf("\n");
        r->tail = (r->tail + 1) % RING_SIZE;
    }
}
```
### Why each barrier is required
- **`smp_wmb()` before publishing `tail`**: Guarantees that all previous writes to `buf` (the actual payload) become visible to other CPUs before they can observe the new `tail`. Without this, a consumer could see an updated `tail` while still seeing stale or partially written data.
- **`smp_rmb()` after reading `head`**: Ensures that any loads performed after reading `head` (e.g., reading payload bytes) happen after all prior loads from the producer have been observed. This prevents the CPU from speculatively loading stale data from earlier in the buffer.
- **No barrier on plain loads/stores**: In this tiny example we only need ordering around the indices, so we use lightweight barriers (`smp_*`) instead of full fences (`mfence`/`lfence`/`sfence`).

### What could go wrong without these barriers?
If we omitted `smp_wmb()`, a CPU might publish a new `tail` value while still holding old copies of some payload bytes in its cache, leading to corrupted messages or out‑of‑bounds reads by the consumer. Conversely, omitting `smp_rmb()` could let the consumer read payload bytes before they are fully written, causing garbled output or crashes if later code assumes valid data.

