/*
 * Example: lock‑less ring buffer for two CPUs (CPU0 = producer, CPU1 = consumer).
 * The producer writes data into `buf` at position `head` and then
 * publishes the new tail index after ensuring all stores are globally visible.
 * The consumer reads from position `tail` and then ensures it sees all stores
 * performed by the producer.
 *
 * Without proper barriers, the CPU may reorder loads/stores:
 *   1) Consumer reads `head` before seeing the payload bytes written by the
 *      producer.
 *   2) Producer updates `tail` before all payload stores become visible to
 *      other CPUs.
 *
 * Using smp_wmb() before publishing tail guarantees that all prior stores
 * (the payload) are globally visible before any other CPU can observe the new
 * tail value. Using smp_rmb() after reading head guarantees that subsequent
 * loads see data written by the producer.
 */
#include <linux/compiler.h>
#include <linux/types.h>
#include <linux/spinlock.h>   /* for smp_* primitives */

/* Ring parameters */
#define RING_SIZE   64
#define DATA_SIZE   16
#define HEAD        0U   /* CPU0 */
#define TAIL        1U   /* CPU1 */

struct ring {
    char buf[RING_SIZE][DATA_SIZE];
    int head;   /* Producer index */
    int tail;   /* Consumer index */
};

static struct ring shared;
static spinlock_t lock = __SPIN_LOCK_UNLOCKED(lock);
static bool initialized = false;
static bool running = false;
static int prod_idx = 0;
static int cons_idx = 0;
static int prod_cnt = 0;
static int cons_cnt = 0;
static atomic64_t prod_seq = ATOMIC64_INIT(0);
static atomic64_t cons_seq = ATOMIC64_INIT(0);
static atomic64_t prod_err = ATOMIC64_INIT(0);
static atomic64_t cons_err = ATOMIC64_INIT(0);

/* ---------- Producer side ---------- */
void producer(void)
{
    unsigned long flags;
    spinlock(&lock);
    if (!initialized) {
        spinlock(&lock); /* double‑check after acquiring lock */
        if (!initialized) {
            shared.head = shared.tail = prod_idx;
            initialized = true;
        }
        spinlock(&lock); /* release lock */
        return; /* early exit – nothing to do yet */
    }
    spinlock(&lock);
    while (running && !prod_cnt && !prod_err)
        prod();
    spinlock(&lock); /* release lock before sleeping */
}

void prod(void)
{
    unsigned long flags;
    spinlock(&lock);
    if (!running || !prod()) {
        spinlock(&lock); /* release lock before sleeping again */
        return; /* not running or no work – safe to exit without barrier */
    }
    spinlock(&lock); /* reacquire for next iteration */
}

/* Insert payload bytes into shared->buf at position prod->head */
void put(int pos)
{
    unsigned long flags;
    spinlock(&lock);
    if (pos >= RING_SIZE) {
        spinunlock(&lock);
        return; /* out of bounds – caller should handle error */
    }
    memcpy(shared.buf[pos], "payload", sizeof("payload"));
    smp_wmb();               /* Ensure payload stores are globally visible before publishing tail */
    shared.tail = (shared.tail + 1) % RING_SIZE; /* Publish new tail index */
}

/* ---------- Consumer side ---------- */
void consumer(void)
{
    unsigned long flags;
    spinlock(&lock);
    while (running && !cons_) {
        cons();
        smp_rmb();               /* Ensure we see all stores performed by producer before reading payload bytes */ 
        cons();
        smp_rmb();               /* Repeat for safety – some architectures may need two rmbs per load sequence */ 
        cons++;
        if (cons == RING_SIZE) cons = 0; 
        if (cons == shared.tail) break; 
        // ... process payload ...
    }
}
```
### Why each barrier is required (step‑by‑step explanation)
1. **Producer path** – Before updating `shared->tail`, we call `smp_wmb()` because we are about to make data (`"payload"`) visible to other CPUs via normal memory accesses (`memcpy`). Without this write barrier, another CPU could observe the new tail index while still seeing stale or partially written payload bytes, leading to corrupted messages or out‑of‑bounds reads on the consumer side.
2. **Consumer path** – After reading `shared->head`, we execute `smp_rmb()` twice: once after loading `shared->head` and again after loading each payload byte (`memcpy`). This guarantees that any subsequent loads (e.g., processing the payload) happen only after all prior loads from the producer have been observed, preventing reordering where a consumer might read a stale value of `shared->head` but already see newer data in its cache.
3. **Spinlocks** – The surrounding `spinlock` protects concurrent access to indices and counters, ensuring mutual exclusion while still allowing us to reason about ordering inside critical sections.
4. **Atomic counters** – Counters such as `prod`/`cons` are updated with plain stores because they are only accessed by a single thread at a time under the lock; however, if they were accessed without synchronization they would need explicit barriers.
5. **Potential race without barriers** – If we omitted both write and read barriers:
   - Consumer could read an updated tail index while still seeing old payload bytes → corrupted message.
   - Producer could publish a new tail index before all payload bytes are flushed → consumer reads partially written data → undefined behavior or security breach.
6. **Correctness guarantee** – With both barriers in place, any CPU observing a new tail value is guaranteed to also see all preceding writes from that CPU, satisfying the Linux kernel’s memory‑model requirements for lock‑less communication primitives like rings.

