/*
 * netfilter_ipv4_fragment_check - Drop fragmented IPv4 packets
 *
 * This function is intended to be used as a Netfilter hook (e.g., NF_INET_PRE_ROUTING).
 * It inspects the skb protocol field and the IPv4 fragment offset to decide
 * whether to accept or drop the packet.
 */
#include <linux/netfilter.h>
#include <linux/skbuff.h>
#include <linux/ip.h>

/* Return 0 if the packet should be accepted, -1 if it must be dropped */
static int netfilter_ipv4_fragment_check(struct sk_buff *skb)
{
    /* Ensure we have at least an IPv4 header before accessing fields */
    if (!pskb_may_pull(skb, sizeof(struct iphdr)))
        return -1; /* Not enough data – cannot safely inspect */

    struct iphdr *iph = ip_hdr(skb);

    /* If the protocol field is not IPv4 (e.g., IPv6), skip this check */
    if (iph->version != 4)
        return 0;

    /* The fragment offset field is in 8‑byte units; non‑zero means a fragment */
    if (iph->frag_off & htons(IP_OFFSET)) {
        /* Fragmented packet – verify that the offset is zero */
        if (iph->frag_off & htons(IP_MF)) {
            /* More fragments – still acceptable for some policies */
            return 0;
        }
        /* Single‑fragment packet with non‑zero offset – drop */
        pr_debug("netfilter: dropping fragmented IPv4 packet (offset=%u)\n",
                 ntohs(iph->frag_off) & IP_OFFSET);
        return -1;
    }

    /* Plain IPv4 packet – accept it */
    return 0;
}
```
**Explanation of key steps**
1. **Header availability** – `pskb_may_pull` guarantees that at least `sizeof(struct iphdr)` bytes are linearized in the skb data area; otherwise we cannot safely read `iph`.
2. **Version check** – ensures we only operate on IPv4 packets; other protocols are passed through.
3. **Fragment offset test** – `iph->frag_off` contains flags defined in `<linux/ip.h>`. The macro `IP_OFFSET` extracts the low‑order byte that holds the fragment offset in 8‑byte units.
   - If any bits of `IPF_*` are set (`IPF_* = htons(IP_*)`), the packet is a fragment.
   - If `IPF_*` includes `IPF_*MF`, more fragments follow; we allow them.
   - If none of those bits are set but any bit of `IPF_*OFFSET` remains, the offset is non‑zero → drop.
4. **Return convention** – Netfilter hooks conventionally return `NF_ACCEPT` (0) or `NF_DROP` (-1). Here we use `-1` for drop, matching typical kernel patterns.
