/*
 * Optimized Internet Checksum (RFC 1071)
 *
 * Input:
 *   - `src` and `dst` – 32‑bit source and destination IP addresses
 *   - `protocol` – IP protocol number (e.g., TCP=6)
 *   - `len` – total length of the pseudo‑header (in bytes)
 *   - `data` – pointer to the payload buffer
 *
 * Output:
 *   - Returns 0 on success, non‑zero on failure.
 */
#include <stdint.h>
#include <stddef.h>

static uint16_t fold(uint32_t sum) {
    /* Add high 16 bits to low 16 bits */
    sum = (sum & 0xFFFF) + (sum >> 16);
    /* If overflow occurred, add back */
    return (sum & 0xFFFF) + (sum >> 16);
}

int ip_tcp_checksum(const uint8_t *src, const uint8_t *dst,
                     uint8_t protocol, size_t len,
                     const uint8_t *data) {
    /* Step 1: Sum all words */
    uint32_t sum = src[0] + src[1] + src[2] + src[3];
    sum += dst[0] + dst[1] + dst[2] + dst[3];
    if (protocol == IPPROTO_TCP) {
        /* TCP pseudo‑header adds length field */
        sum += len;               // length in bytes
        sum += ((uint32_t)(len >> 8)) << 8; // high byte of length
        sum += ((uint32_t)(len >> 16)) << 8; // high byte of length
        sum += ((uint32_t)(len >> 24)) << 8; // high byte of length
    }
    /* Step 2: Fold carries */
    while (sum >> 16)
        sum = fold(sum);

    /* Step 3: Final folding for odd number of bytes */
    if (len & 1) {
        uint8_t last = data[len-1];
        sum += last;
        while (sum >> 8)
            sum = fold(sum);
    }

    /* Step 4: Final folding to produce a single checksum word */
    return fold(sum);
}
```
**Explanation of key points**
- **Word alignment**: The algorithm works on whole bytes; any odd byte at the end is padded with zero before final folding.
- **Folding**: After each addition we add back any overflow (`fold`) to keep the intermediate value within a single word.
- **Protocol handling**: For TCP we add the length field split into four bytes as required by RFC 793.
- **Optimization**: The loop that adds padding bytes runs only once per call, and the final folding loop runs at most twice because each iteration reduces the carry count by at least one bit.
- **Return convention**: `0` indicates success; any non‑zero value signals a checksum mismatch.

This implementation follows RFC 793 §5.5 and RFC 790 §5.4 for pseudo‑header construction.

