/* Helper: return true if the byte is a pointer (high bit set) */
static inline bool is_pointer(uint16_t label)
{
    return (label & 0xc000) != 0;
}

/* Helper: decode a single label (including length byte) */
static void decode_label(const uint8_t *buf, size_t offset,
                        char *out_label, size_t out_len)
{
    uint8_t len = buf[offset];
    if (len == 0) {
        /* Empty label – treat as root label */
        strncpy(out_label, ".", out_len);
        return;
    }
    /* Copy up to len bytes; ensure we never read past the buffer */
    memcpy(out_label, &buf[offset + 1], len);
    out_label[len] = '\0';
}

/* Recursive parser for a single DNS name component.
   Returns true on success and fills `out` with the decoded name.
   The recursion depth is limited to avoid stack overflow.
*/
static bool parse_name(const uint8_t *buf, size_t offset,
                      char *out, size_t out_len)
{
    const uint8_t *p = buf + offset;
    while (*p != '\0') {
        /* Decode length byte */
        uint8_t len = *p++;
        if (len == 0) {
            /* Zero-length label – illegal per RFC 1035 */
            return false;
        }
        if (len > out_len - strlen(out)) {
            /* Buffer would overflow – stop parsing safely */
            return false;
        }
        decode_label(p, p + 1 + len - 1, out + strlen(out), out + strlen(out));
        p += 1 + len; // advance past length byte and label bytes
    }
    return true;
}

