/*
 * validate_ip_header_checksum - Verify the IP header checksum of an incoming
 *                           packet and drop it if the checksum is invalid.
 *
 * @packet: Pointer to the start of the IP header (including the 16‑bit
 *          checksum field). The caller must ensure that at least sizeof(struct
 *          ip_header) bytes are available.
 * @len:   Length of the packet in bytes (excluding any link‑layer trailer).
 *
 * Returns:
 *   0  – Packet is valid; processing continues.
 *  -1  – Packet is dropped because its IP header checksum failed.
 */
int validate_ip_header_checksum(const uint8_t *packet, size_t len)
{
    /* The checksum field occupies bytes 20‑21 of the IPv4 header (offset 16). */
    const uint16_t cksum = *(const uint16_t *)(packet + 20);

    /* Compute one's complement sum over all 16‑bit words. */
    uint32_t sum = 0;
    for (size_t i = 0; i < len; ++i) {
        /* Network byte order: big‑endian. */
        uint16_t word = (uint16_t)packet[i];
        /* Fold carries into lower bits as required by RFC 791. */
        while (word > 0xFFFF) {
            word = (word & 0xFFFF) + (word >> 16);
        }
        sum += word;
    }

    /* One's complement of the sum gives the final checksum value. */
    uint32_t final = ~sum;

    /* If final == cksum, the packet has a valid checksum. */
    if (final == cksum)
        return 0;               /* Valid – continue processing */
    else {
        return -1;              /* Invalid – drop packet */
    }
}
