/* Transformation function – called for each incoming packet */
static void natify(const struct ethhdr *eth, const struct iphdr *iph,
                    const struct tcphdr *tcph)
{
    /* 1️⃣ Update IP header fields */
    iph->daddr = ((struct in3addr *)eth->h_source)->s32[3]; // dst IP from source address
    iph->saddr = ((struct in3addr *)eth->h_dest)->s32[3]; // src IP becomes destination

