    uint16_t csum = ipv4_hdr_cksum((struct iphdr *)iph);
    ((struct iphdr *)iph)->check = csum;

    /* 4️⃣ Re‑calculate TCP header checksum */
    uint16_t tsum = tcp_hdr_cksum((struct tcphdr *)tcph);
    ((struct tcphdr *)tcph)->check = tsum;
