#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Global structures to record allocations */
static void *last_alloc = NULL;
static size_t last_size = 0;
static int leak_detected = 0;

/* Callback invoked by the real malloc/free when they are weak symbols */
void *malloc(size_t size)
{
    /* Record allocation details */
    last_alloc = malloc(size);
    last_size = size;
    return last_alloc;
}

void free(void *ptr)
{
    if (ptr == NULL) {
        fprintf(stderr, "[leak] free(NULL) called\n");
        return;
    }
    /* Record free details */
    if (last_alloc == ptr) {
        /* This is the most recent allocation – could be double‑free or leak */
        if (last_size != 0 && last_size != size) {
            fprintf(stderr, "[leak] double free of %zu bytes at %p\n", last_size, ptr);
            leak_detected = 1;
        } else {
            fprintf(stderr, "[leak] possible leak of %zu bytes at %p\n", last_size, ptr);
            leak_detected = 1;
        }
    } else {
        fprintf(stderr, "[leak] free of unknown pointer %p\n", ptr);
        leak_detected = 1;
    }
}

/* Optional cleanup function for explicit deallocation before exit */
void cleanup()
{
    if (!leak_detected && last_alloc != NULL) {
        /* Attempt to free any remaining heap block – may abort on error */
        free(last_alloc);
    }
}
