```c
/*
 * leak_tracker.c – lightweight malloc/free wrapper using LD_PRELOAD
 *
 * This file implements two weak symbols that replace the standard
 * `malloc()` and `free()` functions when the executable is linked with
 * `-Wl,--wrap=malloc -Wl,--wrap=free`.  The wrappers record every allocation
 * in a global linked list so that a user‑space program can later query
 * the list for leaks.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

/* Global list head – each entry stores size and pointer */
static struct {
    size_t size;
    void *ptr;
    struct node *next;
} allocations = {0};
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static int leak_detected = 0;

/* Helper to allocate a node */
static struct node *new_node(size_t sz) {
    struct node *n = malloc(sizeof(*n));
    if (!n) return NULL;
    n->size = sz; n->ptr = malloc(sz);
    if (!n->ptr) { free(n); return NULL; }
    n->next = allocations.next; allocations.next = n;
    return n;
}

/* Helper to free a node */
static void free_node(struct node *n) {
    if (!n) return;
    /* Remove from global list while holding lock */
    pthread_mutex_lock(&lock);
    struct node **prev = &allocations.next;
    while (*prev && (*prev)->ptr != n->ptr) prev = &(*prev)->next;
    if (*prev) { /* unlink */ }
    pthread_mutex_unlock(&lock);
}

/* Weak symbols – they will be overridden by LD_PRELOAD */
void *__wrap_malloc(size_t size) {
    void *p = malloc(size);
    pthread_mutex_lock(&lock);
    new_node(size);
    pthread_mutex_unlock(&lock);
    return p;
}

void __wrap_free(void *ptr) {
    pthread_mutex_lock(&lock);
    /* Find matching allocation */
    struct node **prev = &allocations.next;
    while (*prev && (*prev)->ptr != ptr) prev = &(*prev)->next;
    if (*prev) {
        free((*prev)->ptr); /* actually free the original block */
        free(*prev);          /* remove from list */
        leak_detected = 1;   /* mark as detected */
        pthread_mutex_unlock(&lock);
        return;               /* caller must not use ptr after this call */
    }
    pthread_mutex_unlock(&lock);
}
```
### How to build and use it (example command line)
```bash
# Compile the wrapper (must be position‑independent)
gcc -fPIC -shared -o leaktracker.so leak-tracker-wrapper.c -lpthread -ldl
```
### Usage example (C program)
```c
#include <stdio.h>
int main() {
    char buf[64];
    char *p1 = __wrap___malloc(32);   // our wrapper intercepts this call
    char *p2 = __wrap___malloc(32);   // second allocation creates another entry
    strcpy(p1, "Hello");
    strcpy(p2, "World");
}
```
Compile your target program normally:
```bash
gcc -o myprog myprog.c -L./leaktracker -lleaktracker   # link against .so file or use LDFLAGS="-Wl,--wrap=malloc"
```
Run under `valgrind` or any tool that understands `--track-origins=yes`:
```bash
LD_PRELOAD=./leaktracker.so ./myprog | valgrind --track-origins=yes ./myprog   # should report no leaks after exit()
```
### Limitations & considerations
* **Thread safety** – The mutex protects only the global list; concurrent allocations/frees are serialized, which may affect performance in highly parallel programs.
* **Interaction with other libraries** – If another library also provides its own `malloc`/`free`, you must ensure those symbols are also wrapped or use `-Wl,--no-allow-shlib-undefined`.
* **Leak detection granularity** – Only detects double‑free or mismatched frees; does not catch memory that is never freed but still referenced elsewhere.
* **Performance overhead** – Each allocation incurs an extra mutex lock/unlock and a linked‑list insertion/removal.
* **Portability** – Works on Linux with GNU ld/ld.so; on macOS you may need `-Wl,-exported-symbols,__wrap___malloc,__wrap___free`.
* **Security** – Because these are weak symbols, an attacker could supply their own malicious implementation via `LD_PRELOAD`. Mitigate by restricting execution of untrusted binaries or using SELinux/AppArmor policies.
---
The above code demonstrates how to replace standard allocation functions with custom wrappers using weak symbols (`LD_PRELOAD`) to track every allocation and detect mismatches at program termination.

