/*
 * safe_mul64 – multiply two unsigned 64‑bit integers and report overflow.
 *
 * Returns:
 *   0  – success (result fits in uint64_t)
 *   -1 – overflow detected (result would not fit in uint64_t)
 *
 * The function uses __builtin_mul_overflow, which is defined by GCC/Clang
 * as:
 *   bool __builtin_mul_overflow(uint64_t a, uint64_t b, uint64_t *res);
 *
 * If the multiplication would overflow, the function returns true and stores
 * the wrapped result in *res; otherwise it returns false.
 */
int safe_mul64(uint64_t a, uint64_t b, uint64_t *out)
{
    uint64_t tmp;
    bool overflow = __builtin_mul_overflow(a, b, &tmp);
    if (overflow) {
        /* tmp holds the low 64 bits of the product; it will be > UINT64_MAX */
        return -1;
    }
    /* tmp now contains the full product; assign it to out */
    *out = tmp;
    return 0;
}
