    int x = 42;
    printf("value=%d\n", x);
    /* Allocate memory for x so its lifetime extends beyond foo() */
    int *p = malloc(sizeof(int));
    assert(p != NULL);   // defensive check
    *p = x;
    return p;            // caller must free()
