#include <stdlib.h>
#include <unistd.h>
#include <sys/prctl.h>
#include <sys/capability.h>
#include <linux/seccomp.h>
#include <linux/filter.h>

/* Helper to print an error and abort */
static void err(const char *msg)
{
    perror(msg);
    exit(EXIT_FAILURE);
}

int main(void)
{
    /* ------------------------------------------------------------ */
    /* 1️⃣ Drop all capabilities – this must be done **before** any */
    /*    seccomp filter is installed because the kernel checks */
    /*    capabilities **after** a successful seccomp check.      */
    /* ------------------------------------------------------------ */
    if (prctl(PR_SET_KEEPCAPS, 0)) {
        err("prctl(PR_SET_KEEPCAPS)");
    }

    /* ------------------------------------------------------------ */
    /* 2️⃣ Query current capabilities so we know what we are dropping */
    /* ------------------------------------------------------------ */
    cap_t caps = cap_get();
    if (!caps) {
        err("cap_get");
        return EXIT_FAILURE;
    }

    printf("Current capabilities:\n");
    for (int i = 0; i < caps->pid; ++i) {
        capdata_t cd;
        capget(&caps->pid[i], &cd);
        printf("\t%d: %d\n", i, cd.effective);
        capset(&caps->pid[i], &cd);
        capset(&caps->pid[i], &cd); // re‑apply for safety
    }

    /* ------------------------------------------------------------ */
    /* 3️⃣ Install a minimal seccomp‑bpf filter that only allows   */
    /*     read(), write(), exit() and nothing else.               */
    /* ------------------------------------------------------------ */
    struct sock_fprog prog = { .len = sizeof(prog), .filter = NULL };

    struct sock_filter filter[] = {
        BPF_STMT(BPF_LD | BPF_W | BPF_ABS,
                 offsetof(struct seccomp, nr)),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K,
                 __NR__read, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP__ALLOW),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K,
                 __NR__write, 0, 1),
        BPF_STMT(BPF_RET | BPF__K, SECCOMP__ALLOW),
        BPF_{RETURN|EXIT},
        BPF_{RETURN|EXIT},
        BPF_{RETURN|EXIT},
        BPF_{RETURN|EXIT},
        BPF_{RETURN|EXIT},
        BPF_{RETURN|EXIT},
        BPF_{RETURN|EXIT},
        BPF_{RETURN|EXIT},
        BPF_{RETURN|EXIT},
        { }   // terminator for libbpf loader
    };

    prog.filter = (void *)filter;

