            || __NR__openat\
            || __NR__open\
            || __NR__creat\
            || __NR__mkdir\
            || __NR__unlink\
            || __NR__rmdir\
            || __NR__link\
            || __NR__symlink\
            || __NR__rename\
            || __NR__chmod\
            || __NR__chown\
            || __NR__lchown\
