#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <elf.h>
#include <fcntl.h>

/* Helper to read a 4‑byte little‑endian value from a file */
static uint32_t read_u32(const void *p)
{
    const uint8_t *b = p;
    return (uint32_t)b[0] | ((uint32_t)b[1] << 8) |
           ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);
}

int main(int argc, char **argv)
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <elf-file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    /* Read the ELF header */
    Elf64_Ehdr ehdr;
    ssize_t n = read(fd, &ehdr, sizeof(ehdr));
    close(fd);
    if (n != sizeof(ehdr)) {
        fprintf(stderr, "Failed to read full ELF header\n");
        return EXIT_FAILURE;
    }

    /* Verify we are dealing with an x86-64 ELF */
    if (memcmp(&ehdr.e_ident[EI_MAG0], ELFMAG, SELFMAG) != 0 ||
        ehdr.e_ident[EI_CLASS] != ELFCLASS64 ||
        ehdr.e_ident[EI_DATA] != ELFDATA2LSB ||
        ehdr.e_machine != EM_X86_64) {
        fprintf(stderr, "Not an x86-64 ELF file\n");
        return EXIT_FAILURE;
    }

    /* Section header table starts after the program headers */
    const Elf64_Shdr *shdr = NULL;
    size_t shnum = ehdr.e_shnum; // number of section headers

    /* Allocate enough space for all sections – we only need the first few entries */
    shdr = calloc((size)(ehdr.e_shnum + 1), sizeof(*shdr));
    if (!shdr) {
        perror("calloc");
        return EXIT_FAILURE;
    }

    /* Seek to the start of the section header table */
    lseek(fd, ehdr.e_shoff, SEEK_SET);

    /* Read each section header into memory */
    for (size_t i = 0; i < shnum; ++i) {
        ssize_t r = read(fd, &shdr[i], sizeof(*shdr));
        if (r != sizeof(*shdr)) {
            fprintf(stderr, "Failed to read section %zu\n", i);
            continue; // skip malformed entry but keep going
        }
        /* Convert virtual address from little‑endian to host order */
        uint64_t vaddr = readl(&shdr[i].sh_addr);
        printf("%s: Virtual address %llu\n", shdr[i].sh_name,
               (unsigned long long)vaddr);
        /* Print human‑readable name – assume .text is named ".text" etc.
         * In real code you would map names from the string table.
         */
        printf("Section name: %s\n", shdr[i].sh_name ? shstrtab + shdr[i].sh_name : "<unnamed>");
        printf("\n");
    }

    free((void *)shdr);
    return EXIT_SUCCESS;
}
