/*
 * pe_check_aslr.c – Simple utility that reads a Windows PE file and reports
 * whether the IMAGE_DLLCHARACTERISTICS_DYNAMIC_BASE flag (ASLR support) is
 * present in its Optional Header.
 *
 * Compile with:
 *   gcc -Wall -Wextra -O2 pe_check_aslr.c -o pe_check_aslr
 *   # On Linux you may need to link against libpeconv or use a Windows SDK.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <windows.h>   // for IMAGE_* definitions on Windows

/* Helper: read exactly 'len' bytes from 'fp' into 'buf'. */
static int read_exact(FILE *fp, void *buf, size_t len)
{
    size_t got = fread(buf, 1, len, fp);
    return (got == len) ? 0 : -1;
}

int main(int argc, char **argv)
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <pe-file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *path = argv[1];
    FILE *fp = fopen(path, "rb");
    if (!fp) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    /* 1. Read DOS header (first 64 bytes). */
    unsigned char dos[64];
    if (read_exact(fp, dos, sizeof(dos)) != 0) {
        fprintf(stderr, "Failed to read DOS header\n");
        fclose(fp);
        return EXIT_FAILURE;
    }

    /* Verify MZ signature at offset 0x0000 */
    if (memcmp(dos + 0x0000, "MZ", 2) != 0) {
        fprintf(stderr, "%s is not a valid PE file\n", path);
        fclose(fp);
        return EXIT_FAILURE;
    }

    /* Read PE signature at offset 0x1FE */
    unsigned char pe[2] = { dos[dos[54] + 54], dos[dos[55] + 55] };
    if (memcmp(pe + 2, "PE", 2) != 0) {
        fprintf(stderr, "%s does not contain a valid PE signature\n", path);
        fclose(fp);
        return EXIT_FAILURE;
    }

    /* Read NT headers structure (size depends on architecture). */
#if defined(_WIN64)
#pragma pack()
#endif
struct _IMAGE_* nt = {0};
memcpy(&nt->Signature,
       dos + sizeof(IMAGE),
       sizeof(nt));
memcpy(&nt->OptionalHeaderSize,
       dos + sizeof(IMAGE_) +
           nt->SizeOfOptionalHeader +
           nt->AddressOfEntryPoint +
           nt->ImageBase,
       sizeof(nt->DllCharacteristics));
memcpy(&nt->DllCharacteristics,
       dos + sizeof(IMAGE_) +
           nt->SizeOfOptionalHeader +
           nt->AddressOfEntryPoint +
           nt->ImageBase +
           nt->DllCharacteristics,
       sizeof(((struct _IMAGE_* *)NULL)->DllCharacteristics));
#if !defined(_WIN64)
/* On x86 we need to skip padding after OptionalHeaderSize */
memcpy(&nt->DllCharacteristics,
       dos + sizeof(IMAGE_) +
           nt->SizeOfOptionalHeader +
           nt->AddressOfEntryPoint +
           nt->ImageBase +
           ((sizeof(((struct _IMAGE_* *)NULL)->DllCharacteristics)) & ~1),
       sizeof(((struct _IMAGE_* *)NULL)->DllCharacteristics));
#endif

/* Extract the DLLCharacteristics field – it starts after ImageBase and DllCharacteristics fields.
   The layout on x86/x64 Windows binaries is:
   [DWORD ImageBase]
   [DWORD DllCharacteristics]
*/
unsigned long dllchar = *(unsigned long *)(dos + sizeof(IMAGE_));
/* The DllCharacteristics field occupies DWORDs starting at offset ImageBase+sizeof(DWORD).
   We can compute its address by adding ImageBase to the base of DllCharacteristics.
*/
unsigned long dllcharptr = doss + sizeof(IMAGE_) + ((unsigned long)(nt->ImageBase & ~((unsigned long)(sizeof(((struct _IMAGE_* *)NULL)->DllCharacteristics)) & ~1)));
if ((dllcharptr >= doss && dllcharptr < doss + sizeof(*nt))) {
    unsigned long flags = dllchar & ~((unsigned long)(sizeof(((struct _IMAGE_* *)NULL)->DllCharacteristics)) & ~1); // strip padding bit if any
}
else {
    fprintf(stderr, "%s: Unable to locate DLL characteristcs field\n", path);
}

/* Test for DYNAMIC BASE flag */
if (flags & IMAGE_DLLCHARACTERISTICS_DYNAMIC_BASE) {
    printf("%s: ASLR enabled (Dynamic Base)\n", path);
} else {
    printf("%s: ASLR not enabled\n", path);
}
```
**Explanation of key steps**
- **DOS header** (`MZ`) confirms we are dealing with a Windows executable.
- **PE signature** (`PE\0\0`) validates that the file follows the Portable Executable format.
- **NT headers** are located immediately after the DOS stub; we copy them into a struct that mirrors Microsoft’s definition.
- **DLL characteristcs** start at `ImageBase` and continue for `SizeOfOptionalHeader` DWORDs. The code computes the exact address by adding `ImageBase` to the base of this field and then masks out any padding bits that may be present on some builds.
- Finally we test `flags & IMAGE_DLLCHARACTERISTICS_DYNAMIC_BASE`. If set, ASLR is enabled; otherwise it is disabled.

**Compilation notes**
- On Linux you can use `libpeconv` or manually parse ELF files instead of Windows APIs.
- For cross‑compilation you may need `-m32`/`-m64` flags matching your target architecture.
- Ensure you have permission to read the target file; otherwise `fopen` will fail.

