#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

/* Maximum chunk size – large enough for typical binaries */
#define CHUNK_SIZE (4096)

/* Helper: compute Shannon entropy for a buffer */
static double shannon_entropy(const unsigned char *buf, size_t len) {
    if (len == 0) return 0.0;
    /* Frequency table for all possible byte values (0‑255) */
    double freq[256] = {0};
    for (size_t i = 0; i < len; ++i) {
        freq[buf[i]]++;
    }
    double ent = 0.0;
    for (int i = 0; i < 256; ++i) {
        if (freq[i] == 0) continue; // avoid division by zero
        ent -= freq[i] / len * log2(freq[i] / len);
    }
    return ent;
}

int main(int argc, char **argv) {
