    size_t bytes_read = fread(buf, 1, CHUNK_SIZE, fp);
    fclose(fp);

    if (bytes_read == 0) {
        fprintf(stderr, "Input file is empty.\n");
        return EXIT_FAILURE;
    }

    double entropy = shannon_entropy(buf, bytes_read);

