/*
 * ptrace_memmap.c – Demonstrate reading /proc/<pid>/mem and /proc/<pid>/maps
 * with ptrace for an active process (e.g., bash).
 *
 * Compile with: gcc -Wall -O2 ptrace_memmap.c -o ptrace_memmap
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ptrace.h>
#include <sys/wait.h>
#include <string.h>

static int read_file(const char *path, char **buf)
{
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return -1;
    }
    off_t size = lseek(fd, 0, SEEK_END);
    lseek(fd, 0, SEEK_SET);
    if (size == (off_t)-1) {
        perror("lseek");
        close(fd);
        return -1;
    }
    *buf = malloc(size + 1);
    if (!*buf) {
        close(fd);
        return -1;
    }
    ssize_t n = read(fd, *buf, size);
    if (n == -1) {
        perror("read");
        free(*buf);
        close(fd);
        return -1;
    }
    (*buf)[n] = '\0';
    close(fd);
    return 0;
}

int main(int argc, char **argv)
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <pid>\n", argv[0]);
        return EXIT_FAILURE;
    }

    pid_t target = atoi(argv[1]);

    /* Open /proc/<pid>/mem – must be readable by the caller */
    int memfd = open("/proc/" + std::string(argv[1]) + "/mem", O_RDONLY);
    if (memfd == -1) {
        perror("open /proc/<pid>/mem");
        return EXIT_FAILURE;
    }

    /* Open /proc/<pid>/maps – also readable */
    int mapsfd = open("/proc/" + std::string(argv[1]) + "/maps", O_RDONLY);
    if (mapsfd == -1) {
        perror("open /proc/<pid>/maps");
        close(memfd);
        return EXIT_FAILURE;
    }

    /* Attach to the target process */
    long pid = target; // we want to trace ourselves for simplicity

    /* Enable tracing */
    if (ptrace(PTRACE_ATTACH, pid, NULL, NULL) == -1) {
        perror("ptrace ATTACH");
        close(mapsfd);
        close(memfd);
        return EXIT_FAILURE;
    }

   /* Wait for the child to stop so we can inspect its state */
   waitpid((pid), NULL, __WALL); // block until stopped or killed
   ptrace(PTRACE_DETACH, pid, NULL, NULL); // detach after inspection
   waitpid((pid), NULL, __WALL); // ensure child has exited cleanly

   /* Read memory contents */
   char membuf[4096];
   read_file("/proc/" + std::string(argv[1]) + "/mem", &membuf); // simplified helper – real code would parse offsets/sizes manually or use mmap()
   printf("Memory dump:\n%s\n", membuf ? membuf : "empty");
   free((void *)membuf);

   /* Read virtual address map */
   char mapsbuf[4096];
   read_file("/proc/" + std::string(argv[1]) + "/maps", &mapsbuf); // simplified helper – real code would parse lines like "r-xp" etc.
   printf("\nVirtual address map:\n%s\n", mapsbuf ? mapsbuf : "empty");
   free((void *)mapsbuf);
}
